import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P01-Programming-thinking/22-Can-computer-programs-really-kill-people.html","title":"22-灰度测试：让错误止步于小范围的“防火墙”","lang":"zh-CN","frontmatter":{"title":"22-灰度测试：让错误止步于小范围的“防火墙”","icon":"read","date":"2025-04-22T20:34:18.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1748754423000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":18,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":4}],"changelog":[{"hash":"ff4587c74d1c76d3aac787d3c96ea9dd9fecd743","time":1748754423000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更改文件夹名称"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"af07943021cfb3125decea5ffbeee6321dabd9b2","time":1745393076000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"fa58d6ee5e02f6df6d5c3088408acada844b9aa4","time":1745389451000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"添加插图"},{"hash":"417b82948d572270fb9a882378267a30fe26af97","time":1745382141000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Implement code changes to enhance functionality and improve performance"},{"hash":"ee5a854d9298a115109d1b40af33710f33b198e4","time":1745381054000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新文章内容，添加微信日活数据及灰度测试的生活实例，增强用户理解"},{"hash":"baaa029f1d72a6b020f4e3d94fc4f9e6ded30cea","time":1745369442000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Implement multiple code changes to enhance functionality and improve performance"},{"hash":"186b801cf43cd148ac549908c91a2a5231c1f641","time":1745330808000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新文章标题并添加内容，强调程序潜在风险与灰度测试的重要性"},{"hash":"4d098f34b968c7f9162e7d143141d46669c76d6e","time":1745325668000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add articles on programming and cooking: \\"Can computer programs really kill people?\\" and \\"清蒸鲈鱼\\""},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"f14b0cca174ae138ce78063f95445916775cebdb","time":1718679320000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"11"},{"hash":"e6ce4e085767c4f5b781fafab34fce9bb8a77757","time":1717922615000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"192.168.3.12"},{"hash":"698822ef18765f0a40a5fe8d17c8e37745f728e7","time":1717398270000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"2024-06-03 15:03:05"},{"hash":"772c411a931f42f9f56579305c16a96c1c834525","time":1675582584000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"e6a0f505dee0408ae039742ed8b7c873f3ccba3b","time":1675328574000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"添加 Python 教程"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":7.44,"words":2231},"filePathRelative":"column/Python-Programming-Course/P01-Programming-thinking/22-Can-computer-programs-really-kill-people.md"}`),a={name:`22-Can-computer-programs-really-kill-people.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<figure><img src="/assets/raw-20250423121032082-Dht9Ahuk.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>你有没有见过那种自信满满的程序员，写完代码拍拍胸脯说：“放心吧，绝对没问题！”可话虽这么说，你真的就能百分百放心吗？</p><p>有些错误啊，还真不是在电脑上点几下“运行”就能发现的。有时候，程序在电脑上跑得挺顺，但放到现实世界中，反而可能引发一连串意想不到的麻烦。</p><p>这些特别的情况（错误），程序员在编写程序的时候，不太可能预先想到——或者至少是，不太可能全部都预先想到。很多只有在实际使用中才会出现。</p><p>别不信，我给你讲个真事。</p><h2 id="_1-那台-治病-的机器-居然" tabindex="-1"><a class="header-anchor" href="#_1-那台-治病-的机器-居然"><span>1. 那台“治病”的机器，居然……</span></a></h2><figure><img src="/assets/raw-20250423140133230-BPjEtIcU.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>上世纪末，一家技术公司推出了一种用于治疗癌症的高能射线设备。你可以理解成超级加强版的 X 光机，能精准地用射线杀死癌细胞。听起来是不是挺高科技的？</p><p>可惜的是，这台设备在运行中出现了严重的故障。有些患者在接受治疗时，身体突然像被火灼一样剧痛，甚至有的直接从治疗床上跳了起来。</p><figure><img src="/assets/raw-20250423140521843-CjlKSb3R.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>调查后发现，这台机器在某些时候会<strong>意外提升射线强度</strong>，而且是一百多倍的那种“超载”！这不是闹着玩的，高强度射线不仅杀癌细胞，也能伤及健康细胞，甚至直接危及生命。最终，有六位病人因此受伤，其中四位不幸去世。</p><p>这事可严重了，程序员们赶紧就跑来对机器进行了检查。可检查来检查去，按照正常的操作，程序是不会出问题的呀。难道是有人违规操作了程序？</p><p>可给人治病是生死攸关的大事，医生也肯定不会乱操作啊。这下调查<strong>陷入了僵局</strong>。</p><p>那么问题来了，为什么这样的严重漏洞没有在开发阶段发现呢？程序员可是做了不少测试啊。</p><p>调查陷入了僵局，直到有一位医生回忆起了一个小细节：机器出故障的时候，会弹出一个提示，这一线索成为突破口。抓住这一点，程序员们一分析发现，这个错误竟然是因为正常操作引起的。</p><p>可是，正常操作怎么会导致悲剧的发生呢，是不是有的新手医生笨手笨脚的，操作不够熟练啊？<strong>恰恰相反</strong>，问题的原因就是，医生操作机器的时候<strong>太过熟练</strong>了。</p><p>这就奇怪了，操作得太过熟练难道不好吗？</p><h2 id="_2-出事的原因竟然是-医生太熟练了" tabindex="-1"><a class="header-anchor" href="#_2-出事的原因竟然是-医生太熟练了"><span>2. 出事的原因竟然是：医生太熟练了！</span></a></h2><p>没错，就是这个让人难以置信的结论：<strong>操作者动作太快了</strong>。</p><p>程序在设计时默认输入会有一点点间隔，但医生操作太熟练，连续输入速度飞快，结果导致系统内部数据处理顺序错乱，从而触发了那个隐藏的 bug。（省字版：<strong>信息输入得就太快了，机器一下子处理不过来</strong>。其实人也是一样，一下子给的信息太多也会处理不过来。）</p><p>你看，这就是我刚才跟你说的，这类问题程序员压根就不太可能想的到。这类问题平时根本不容易发现，程序运行再多遍都没问题。</p><p>因为只有在实际使用中，这样的问题才会暴露出来。程序员在设计程序的时候，不太可能想到：因为“<strong>使用者太过熟练</strong>”导致输入的数据过快，计算机数据混乱。</p><p><s>那这一类问题，有什么 debug 的方法吗？</s></p><p>所以你看，哪怕程序在表面上看不出毛病，它也可能在“边界条件”下突然崩溃。这就需要一种特殊的测试方式——<strong>灰度测试</strong>。</p><h2 id="_3-什么是-灰度测试" tabindex="-1"><a class="header-anchor" href="#_3-什么是-灰度测试"><span>3. 什么是“灰度测试”？</span></a></h2><p>灰度测试，其实就是一边上线、一边试错。这种方法可以让几万人甚至几十万人一起帮程序员测试程序，这种测试方法叫做：<strong>灰度测试</strong>。</p><p>那具体是怎么个试法？程序员不会一下子让所有用户都用新版本，而是先选一小撮人——比如10%的用户——来试试水。</p><p>这样做的好处是，一旦出现问题，受影响的范围会很小。就像给程序穿上了一件“缓冲衣”，先撞一下墙看看痛不痛，没问题再放开使用。</p><p>而你手机上那些 App，像什么聊天软件、微信、QQ 等软件，其实几乎天天都在用这种方式在悄悄更新。</p><p><strong>为了让你更好的理解，我们举个例子：</strong></p><figure><img src="/assets/image-20250423084550676-B0ixeJdu.png" alt="微信视频号截图" tabindex="0" loading="lazy"><figcaption>微信视频号截图</figcaption></figure><figure><img src="/assets/image-20250423084647817-C_sJdYXl.png" alt="微信视频号评论显示 IP 地址" tabindex="0" loading="lazy"><figcaption>微信视频号评论显示 IP 地址</figcaption></figure><p>假如现在微信要上新功能，可以在视频号里面显示 IP 地址这个功能（包括评论显示 IP）。那为了确保新版本的微信能正常运行，程序员们肯定会绞尽脑汁，排除掉每一种出错的可能性。想来想去，觉得没啥问题了，诶，就要请出灰度测试了。</p><p>程序员会从微信用户里选出一小部分，比如<strong>10%</strong>吧，先请他们更新自己的微信。</p><p>10% 这个数字听起来不大，但在微信这个软件上。微信可是日活：8.43亿（2024年），所以10%也已经有很多很多人了。这些参加灰度测试的用户，使用的手机，<strong>差不多覆盖了市场上所有的手机型号</strong>。</p><p>如果有些手机屏幕尺寸比较特别，IP 位置显示（渲染）的位置不太对劲。那么，程序员们就在这个阶段发现问题，并且解决掉。这样一来，程序错误就只会影响很少的人，绝大多数的人还可以正常使用。</p><p>Tips：现在其实有些 APP 很多数据代码都是通过请求网络来实现实时更新，不用推送新版本。所以有时这样的灰度测试是悄悄的更新～</p><h2 id="_4-灰度测试不仅管用-还能-读心术" tabindex="-1"><a class="header-anchor" href="#_4-灰度测试不仅管用-还能-读心术"><span>4. 灰度测试不仅管用，还能“读心术”</span></a></h2><p>除了发现 bug，灰度测试还有另一个厉害的地方：<strong>预测用户反应</strong>。</p><p>换句话说就是灰度测试的优点：<strong>判断这个更新符不符合大家的预期</strong>。</p><p>如果更新完之后，这10%的人都觉得，IP 地址这个功能很鸡肋、暴露隐私，都要求改回原来的样子。这样一来，这次更新很可能就会取消。这一点，靠检查编程代码是发现不了的。（但是 IP 地址显示是势在必行！不可能取消，具体原因自行查阅）</p><p>这种“听听风声再决定”的方式，是写代码的人光靠想，是想不到的。</p><h2 id="_5-灰度测试-也能-下厨房" tabindex="-1"><a class="header-anchor" href="#_5-灰度测试-也能-下厨房"><span>5. 灰度测试，也能“下厨房”？</span></a></h2><figure><img src="/assets/fff-D5L9y-a9.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>说实话，灰度测试的思维方式不仅适用于写程序，在生活中也同样管用。</p><p>比如你妈妈第一次尝试做海鲜汤，爸爸说放点胡椒味道更棒，妈妈说加点醋更鲜美。此时，如果直接把调料（胡椒、醋）放进整锅汤里，那万一味道翻车，可就损失惨重了。（一锅都喝不了）</p><p>看完前面的灰度测试的例子，想想现在要怎么办？</p><figure><img src="/assets/ssss-Dg6TpIUy.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>聪明的做法当然是——<strong>舀一小碗</strong>出来，各自加点调料尝一尝。哪个更好喝，再决定怎么调整整锅，这样才最安全，这不就是“灰度测试”吗？</p><p>现在你明白了吧？程序员用灰度测试提高程序质量，而我们在生活中也可以用相似的方法避免风险，确保每一步都稳妥有效。</p><h2 id="_6-写程序-不能靠拍脑袋" tabindex="-1"><a class="header-anchor" href="#_6-写程序-不能靠拍脑袋"><span>6. 写程序，不能靠拍脑袋</span></a></h2><p>写程序，其实就像造飞机：你可以设计得再漂亮、测试得再充分，总会有“飞起来之后才知道”的问题。</p><p>所以，不仅要自己小心翼翼调试，还要设计好各种“保险机制”，甚至请大家帮你一起找问题。这些，才是真正专业的编程态度。</p><p>而你，只要记住这一点：<strong>一个看似正常的程序，也可能藏着灾难的伏笔。</strong></p>`,54)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};